-- Mutation fixture: its own synthetic customer, restored by the enclosing rollback.
create function pg_temp.mid(n integer) returns uuid language sql immutable as $$select ('44005000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into public.customers(id,name) values(pg_temp.mid(1),'Syntetiskt ändringsprov');
insert into public.organizers(id,customer_id,name,type) values(pg_temp.mid(2),pg_temp.mid(1),'Syntetiskt ändringsprov','Kommun');
insert into public.identities(id,issuer,subject) select pg_temp.mid(n),'https://mutation.example.test',n::text from generate_series(10,13)n;
insert into public.memberships(id,identity_id,customer_id) select pg_temp.mid(n+10),pg_temp.mid(n),pg_temp.mid(1) from generate_series(10,13)n;
insert into public.school_units(id,organizer_id,code,name,municipality_code) select pg_temp.mid(n),pg_temp.mid(2),'440050'||n,'Provskola '||n,'0180' from generate_series(30,32)n;
insert into public.offerings(id,organizer_id,unit_id,kind,name,cohort,start_year) select pg_temp.mid(n+10),pg_temp.mid(2),pg_temp.mid(n),'grundskola','Provutbildning','Provkull',2026 from generate_series(30,32)n;
insert into public.offerings(id,organizer_id,unit_id,kind,name,cohort,start_year) values(pg_temp.mid(43),pg_temp.mid(2),pg_temp.mid(30),'grundskola','Annan utbildning','Provkull',2026);
insert into public.school_classes(id,customer_id,organizer_id,unit_id,offering_id,name,start_year) select pg_temp.mid(n+20),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(n),pg_temp.mid(n+10),'PROV'||n,2026 from generate_series(30,32)n;
insert into public.school_classes(id,customer_id,organizer_id,unit_id,offering_id,name,start_year) values(pg_temp.mid(53),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(30),pg_temp.mid(43),'ANNAN',2026);
insert into public.access_assignments(id,membership_id,customer_id,organizer_id,function,profile_id,scope_kind) values(pg_temp.mid(60),pg_temp.mid(20),pg_temp.mid(1),pg_temp.mid(2),'huvudman','synthetic-v1','school');
insert into public.mandate_units select pg_temp.mid(60),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(n) from generate_series(30,32)n;
create temp table mutation_roles(name text primary key,id uuid);
create function pg_temp.ma(name text) returns void language plpgsql as $$declare a public.access_assignments; begin
select * into a from public.access_assignments where id=case when name='hm' then pg_temp.mid(60) else (select r.id from mutation_roles r where r.name=ma.name) end;
perform set_config('app.customer_id',a.customer_id::text,true),set_config('app.assignment_id',a.id::text,true),set_config('app.membership_id',a.membership_id::text,true),set_config('app.identity_id',(select identity_id::text from public.memberships where id=a.membership_id),true); end$$;
select pg_temp.ma('hm');
insert into mutation_roles values('principal',public.phase3_grant_mandate(jsonb_build_object('membershipId',pg_temp.mid(21),'function','rektor','scopeKind','school','unitIds',jsonb_build_array(pg_temp.mid(30),pg_temp.mid(31),pg_temp.mid(32)))));
select pg_temp.ma('principal');
insert into mutation_roles select label,public.phase3_grant_mandate(jsonb_build_object('membershipId',member,'function','administrator','scopeKind','school','unitIds',jsonb_build_array(pg_temp.mid(30),pg_temp.mid(31)))) from (values('admin',pg_temp.mid(22)),('admin2',pg_temp.mid(23)))r(label,member);
insert into public.pupils(id,customer_id,organizer_id,display_name,personal_number,anonymous_name) values(pg_temp.mid(70),pg_temp.mid(1),pg_temp.mid(2),'Syntetisk elev','TEST-20100101-0014','Elev prov');
insert into public.pupil_placements(id,customer_id,organizer_id,pupil_id,unit_id,offering_id,starts_on) values(pg_temp.mid(80),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),pg_temp.mid(30),pg_temp.mid(40),public.app_today()-100);
insert into public.pupil_class_memberships(id,customer_id,organizer_id,pupil_id,unit_id,class_id,placement_id,starts_on) values(pg_temp.mid(90),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),pg_temp.mid(30),pg_temp.mid(50),pg_temp.mid(80),public.app_today()-100);
insert into public.pupil_home_municipalities(id,customer_id,organizer_id,pupil_id,municipality_code,starts_on) values(pg_temp.mid(100),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),'0180',public.app_today()-100);
create function pg_temp.mreq(kind text,payload jsonb,v integer default null) returns jsonb language sql as $$select jsonb_build_object('pupilId',pg_temp.mid(70),'schoolYear',extract(year from public.app_today())::integer-case when extract(month from public.app_today())<7 then 1 else 0 end,'caseId',null,'expectedVersion',coalesce(v,(select version from public.pupils where id=pg_temp.mid(70))),'kind',kind,'payload',payload)$$;
select pg_temp.ma('admin');

savepoint mutation_start;
select has_function('public','phase4_change_pupil',array['jsonb'],'atomic mutation entrypoint exists');
select is(public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Ändrat provnamn"}'))->>'kind','success','basics succeeds');
select is((select version from public.pupils where id=pg_temp.mid(70)),2,'mutation increments aggregate version');
select is((select count(*) from public.pupil_field_history where pupil_id=pg_temp.mid(70)),1::bigint,'one changed field gets one history row');
select is((select actor_id from public.pupil_field_history where pupil_id=pg_temp.mid(70)),pg_temp.mid(22),'history actor derives from live mandate');
select is((select before_value#>>'{}' from public.pupil_field_history where pupil_id=pg_temp.mid(70)),'Syntetisk elev','history preserves old value');
select is((select source from public.pupil_field_state where pupil_id=pg_temp.mid(70) and field='displayName'),'manual','manual origin is recorded');
select is(public.phase4_change_pupil(pg_temp.mreq('class',jsonb_build_object('placementId',pg_temp.mid(80),'classId',pg_temp.mid(53),'startsOn',public.app_today()+1,'endsOn',null)))->>'kind','success','class change is atomic');
select is((select offering_id from public.pupil_placements where id=pg_temp.mid(80)),pg_temp.mid(40),'class change never changes education');
select is((select ends_on from public.pupil_class_memberships where id=pg_temp.mid(90)),public.app_today(),'old class ends day before next class');
select is((select count(*) from public.pupil_class_memberships where pupil_id=pg_temp.mid(70)),2::bigint,'class history is retained');
select is(public.phase4_change_pupil(pg_temp.mreq('municipality',jsonb_build_object('municipalityCode','0180','startsOn',public.app_today()+1,'endsOn',null)))->>'kind','success','municipality creates a dated period');
select is((select ends_on from public.pupil_home_municipalities where id=pg_temp.mid(100)),public.app_today(),'old municipality period closes');
select ok((select after_value ?& array['id','municipalityCode','startsOn','endsOn'] from public.pupil_field_history where pupil_id=pg_temp.mid(70) and field='municipality' limit 1),'municipality history carries stable period identity');

select is(public.phase4_change_pupil(pg_temp.mreq('transfer',jsonb_build_object('placementId',pg_temp.mid(80),'unitId',pg_temp.mid(31),'educationId',pg_temp.mid(41),'startsOn',public.app_today()+10,'endsOn',null)))->>'kind','success','school transfer succeeds');
select is((select ends_on from public.pupil_placements where id=pg_temp.mid(80)),public.app_today()+9,'previous placement ends before transfer');
select ok(not exists(select 1 from public.pupil_class_memberships c join public.pupil_placements p on p.id=c.placement_id where c.pupil_id=pg_temp.mid(70) and not daterange(c.starts_on,c.ends_on,'[]')<@daterange(p.starts_on,p.ends_on,'[]')),'all classes remain within placement');
select is((select count(*) from public.pupil_placements where pupil_id=pg_temp.mid(70)),2::bigint,'transfer preserves prior placement');
rollback to mutation_start;
select is(public.phase4_change_pupil(pg_temp.mreq('education',jsonb_build_object('placementId',pg_temp.mid(80),'educationId',pg_temp.mid(43),'startsOn',public.app_today()+10)))->'body'->'warnings','["class-education-mismatch"]'::jsonb,'education preserves class with explicit mismatch warning');
select is((select count(distinct class_id) from public.pupil_class_memberships where pupil_id=pg_temp.mid(70)),1::bigint,'education does not automatically change class');
select is((select count(*) from public.pupil_placements where pupil_id=pg_temp.mid(70)),2::bigint,'education keeps old dated placement');
select ok(not exists(select 1 from public.pupil_class_memberships c join public.pupil_placements p on p.id=c.placement_id where c.pupil_id=pg_temp.mid(70) and not daterange(c.starts_on,c.ends_on,'[]')<@daterange(p.starts_on,p.ends_on,'[]')),'split education keeps complete class periods contained');
rollback to mutation_start;
select is(public.phase4_change_pupil(pg_temp.mreq('end-placement',jsonb_build_object('placementId',pg_temp.mid(80),'endsOn',public.app_today()-1)))->>'kind','success','placement can end leaving history only');
select is((select ends_on from public.pupil_class_memberships where id=pg_temp.mid(90)),public.app_today()-1,'ending placement closes crossing class');
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Nekat"}'))$q$,'P0002',null,'D20 history-only pupil cannot be changed');
rollback to mutation_start;
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('class',jsonb_build_object('placementId',pg_temp.mid(80),'classId',pg_temp.mid(51),'startsOn',public.app_today()+1,'endsOn',null)))$q$,'22023',null,'foreign-school class rejected');
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('transfer',jsonb_build_object('placementId',pg_temp.mid(80),'unitId',pg_temp.mid(32),'educationId',pg_temp.mid(42),'startsOn',public.app_today()+1,'endsOn',null)))$q$,'42501',null,'school outside mandate rejected');
select is(public.phase4_change_pupil(pg_temp.mreq('class',jsonb_build_object('placementId',pg_temp.mid(80),'classId',pg_temp.mid(50),'startsOn',public.app_today()-101,'endsOn',null)))->'details'->>'reason','outside-placement','whole class period must fit placement');
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Nekat","actorId":"spoof"}'))$q$,'22023',null,'client cannot specify actor');
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('basics','{"personalNumber":"191001010000"}'))$q$,'22023',null,'nonallowlisted personal number rejected');
insert into public.pupil_field_state(customer_id,organizer_id,pupil_id,field,source,actor_id,revision) values(pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),'displayName','simulated',pg_temp.mid(22),1);
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Nekat"}'))$q$,'42501',null,'source-owned field cannot be overwritten');
update public.pupil_field_state set local_correction=true where pupil_id=pg_temp.mid(70);
select is(public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Tillåten rättelse"}'))->>'kind','success','existing explicit local correction can be edited');
select is((select source from public.pupil_field_history where pupil_id=pg_temp.mid(70) and field='displayName' order by revision desc limit 1),'manual','local correction history records actual manual writer');
select ok((select local_correction from public.pupil_field_state where pupil_id=pg_temp.mid(70) and field='displayName'),'local correction marker retained');
rollback to mutation_start;
update public.pupils set protected_identity=true where id=pg_temp.mid(70);
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Nekat"}'))$q$,'P0002',null,'protected pupil anonymous admin cannot mutate');
select pg_temp.ma('hm');
select public.phase4_grant_protected_permission((select id from mutation_roles where name='admin'),pg_temp.mid(30));
select pg_temp.ma('admin');
select is(public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Tillåten"}'))->>'kind','success','explicit protected grant enables mutation');
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('transfer',jsonb_build_object('placementId',pg_temp.mid(80),'unitId',pg_temp.mid(31),'educationId',pg_temp.mid(41),'startsOn',public.app_today()+1,'endsOn',null)))$q$,'42501',null,'protected transfer also requires destination grant');
select pg_temp.ma('principal');
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Nekat"}'))$q$,'42501',null,'principal has no register mutation authority');
rollback to mutation_start;
select ok(has_function_privilege('skolplattform_worker','public.phase4_change_pupil(jsonb)','EXECUTE'),'mutation open to Worker after 04-23 audited API grant');


-- Future plans must survive attempts to insert an overlapping relation.
rollback to mutation_start;
update public.pupil_placements set ends_on=public.app_today()+29 where id=pg_temp.mid(80);
update public.pupil_class_memberships set ends_on=public.app_today()+29 where id=pg_temp.mid(90);
insert into public.pupil_placements(id,customer_id,organizer_id,pupil_id,unit_id,offering_id,starts_on) values(pg_temp.mid(81),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),pg_temp.mid(31),pg_temp.mid(41),public.app_today()+30);
select is(public.phase4_change_pupil(pg_temp.mreq('transfer',jsonb_build_object('placementId',pg_temp.mid(80),'unitId',pg_temp.mid(31),'educationId',pg_temp.mid(41),'startsOn',public.app_today()+10,'endsOn',null)))->>'kind','conflict','transfer cannot destroy future placement');
select is((select ends_on from public.pupil_placements where id=pg_temp.mid(80)),public.app_today()+29,'conflicting transfer leaves original period unchanged');
select is((select count(*) from public.pupil_field_history where pupil_id=pg_temp.mid(70)),0::bigint,'period conflict writes no history');
select is(public.phase4_change_pupil(pg_temp.mreq('class',jsonb_build_object('placementId',pg_temp.mid(80),'classId',pg_temp.mid(53),'startsOn',public.app_today()+1,'endsOn',null)))->'details'->>'reason','outside-placement','open class cannot exceed finite placement');
rollback to mutation_start;
update public.pupil_class_memberships set ends_on=public.app_today()+9 where id=pg_temp.mid(90);
insert into public.pupil_class_memberships(id,customer_id,organizer_id,pupil_id,unit_id,class_id,placement_id,starts_on) values(pg_temp.mid(91),pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),pg_temp.mid(30),pg_temp.mid(53),pg_temp.mid(80),public.app_today()+10);
select is(public.phase4_change_pupil(pg_temp.mreq('class',jsonb_build_object('placementId',pg_temp.mid(80),'classId',pg_temp.mid(53),'startsOn',public.app_today()+1,'endsOn',null)))->>'kind','conflict','new class cannot overwrite scheduled future class');
select is(public.phase4_change_pupil(pg_temp.mreq('end-placement',jsonb_build_object('placementId',pg_temp.mid(80),'endsOn',public.app_today()+2)))->>'kind','conflict','ending placement cannot erase future class');
select is(public.phase4_change_pupil(pg_temp.mreq('education',jsonb_build_object('placementId',pg_temp.mid(80),'educationId',pg_temp.mid(43),'startsOn',public.app_today()+1)))->>'kind','success','education split preserves future class');
select ok(exists(select 1 from public.pupil_class_memberships where id=pg_temp.mid(91) and starts_on=public.app_today()+10 and class_id=pg_temp.mid(53)),'scheduled class retains stable identity and dates');
rollback to mutation_start;
-- A late history failure rolls back pupil fields, revision and origin together.
create function pg_temp.fail_history() returns trigger language plpgsql as $$begin if new.pupil_id=pg_temp.mid(70) then raise exception 'synthetic history failure' using errcode='P0001'; end if; return new; end$$;
create trigger phase4_mutation_history_failure before insert on public.pupil_field_history for each row execute function pg_temp.fail_history();
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Återställ"}'))$q$,'P0001',null,'history failure stops mutation');
select is((select version from public.pupils where id=pg_temp.mid(70)),1,'history failure retains version');
select is((select display_name from public.pupils where id=pg_temp.mid(70)),'Syntetisk elev','history failure retains original field');
drop trigger phase4_mutation_history_failure on public.pupil_field_history;
rollback to mutation_start;
-- Test an actual Worker invocation through the migration grant (04-23); no test-local grant.
create temp table worker_mutation_request as select pg_temp.mreq('basics','{"displayName":"Workerprov"}') as request;
grant select on worker_mutation_request to skolplattform_worker;
set local role skolplattform_worker;
select is(public.phase4_change_pupil((select request from worker_mutation_request))->>'kind','success','direct Worker invocation enforces server-context mutation');
reset role;
rollback to mutation_start;
select ok(has_function_privilege('skolplattform_worker','public.phase4_change_pupil(jsonb)','EXECUTE'),'Worker execute comes from the migration and survives rollback');


rollback to mutation_start;
insert into public.pupils(id,customer_id,organizer_id,display_name,personal_number,anonymous_name) values(pg_temp.mid(71),pg_temp.mid(1),pg_temp.mid(2),'Annan syntetisk elev','TEST-20100101-0022','Elev andra');
select throws_ok($q$select public.phase4_change_pupil(pg_temp.mreq('basics','{"displayName":"Får inte sparas","personalNumber":"TEST-20100101-0022"}'))$q$,'22023','Invalid register change','duplicate identity has generic error without raw constraint values');
select is((select count(*) from public.pupil_field_history where pupil_id=pg_temp.mid(70)),0::bigint,'late constraint failure rolls back all field history');
select is((select version from public.pupils where id=pg_temp.mid(70)),1,'late constraint failure rolls back aggregate version');
select is((select display_name from public.pupils where id=pg_temp.mid(70)),'Syntetisk elev','late constraint failure rolls back other field');
rollback to mutation_start;


insert into public.pupil_field_state(customer_id,organizer_id,pupil_id,field,source,actor_id,revision) values(pg_temp.mid(1),pg_temp.mid(2),pg_temp.mid(70),'placement','simulated',pg_temp.mid(22),1);
select is(public.phase4_change_pupil(pg_temp.mreq('class',jsonb_build_object('placementId',pg_temp.mid(80),'classId',pg_temp.mid(53),'startsOn',public.app_today()+1,'endsOn',null)))->>'kind','success','source-owned placement does not block independently app-owned class');
select is((select source from public.pupil_field_state where pupil_id=pg_temp.mid(70) and field='placement'),'simulated','class change leaves placement ownership unchanged');
rollback to mutation_start;

rollback;
